import * as T from '../vendor/three.module.js';
export class Effects{
 constructor(scene){this.count=420;this.points=[];this.positions=new Float32Array(this.count*3);this.colors=new Float32Array(this.count*3);this.cursor=0;for(let i=0;i<this.count;i++)this.points.push({life:0,pos:new T.Vector3(),vel:new T.Vector3(),color:new T.Color()});const g=new T.BufferGeometry();g.setAttribute('position',new T.BufferAttribute(this.positions,3));g.setAttribute('color',new T.BufferAttribute(this.colors,3));this.mesh=new T.Points(g,new T.PointsMaterial({size:.55,vertexColors:true,transparent:true,opacity:.8,blending:T.AdditiveBlending,depthWrite:false}));this.mesh.frustumCulled=false;scene.add(this.mesh);}
 emit(pos,vel,color,life=.6){const p=this.points[this.cursor++%this.count];p.pos.copy(pos);p.vel.copy(vel);p.life=life;p.maxLife=life;p.color.set(color);}
 burst(pos,color=0xffbe68){for(let i=0;i<70;i++)this.emit(pos,new T.Vector3((Math.random()-.5)*28,(Math.random()-.3)*20,(Math.random()-.5)*28),color,.5+Math.random());}
 update(dt,player,mesh,track){if(player.speed>20&&player.respawn<=0){const f=track.frame(player.s);for(const side of [-1,1]){const pos=mesh.position.clone().addScaledVector(f.f,-3).addScaledVector(f.r,side*1.9);this.emit(pos,f.f.clone().multiplyScalar(-player.speed*.12),player.boosting?0xcaff69:0x55dfff,player.boosting?.65:.28);if(player.drifting)this.emit(pos,new T.Vector3((Math.random()-.5)*10,Math.random()*3,(Math.random()-.5)*10),0xcaff69,.5);}}
 for(let i=0;i<this.count;i++){const p=this.points[i];p.life-=dt;if(p.life>0){p.pos.addScaledVector(p.vel,dt);this.positions.set(p.pos.toArray(),i*3);const fade=p.life/p.maxLife;this.colors.set([p.color.r*fade,p.color.g*fade,p.color.b*fade],i*3);}else{this.positions[i*3+1]=-10000;}}this.mesh.geometry.attributes.position.needsUpdate=true;this.mesh.geometry.attributes.color.needsUpdate=true;}
}
